package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)

	var n, m int
	fmt.Fscan(in, &n, &m)

	a := make([]int, n)
	b := make([]int, m)

	for i := 0; i < n; i++ {
		fmt.Fscan(in, &a[i])
	}
	for i := 0; i < m; i++ {
		fmt.Fscan(in, &b[i])
	}

	// Check for common digit
	common := -1
	for _, x := range a {
		for _, y := range b {
			if x == y {
				if common == -1 || x < common {
					common = x
				}
			}
		}
	}

	if common != -1 {
		fmt.Println(common)
		return
	}

	// No common digit: form smallest two-digit number from min digits
	minA := 10
	minB := 10
	for _, x := range a {
		if x < minA {
			minA = x
		}
	}
	for _, y := range b {
		if y < minB {
			minB = y
		}
	}

	// Smallest two-digit number using minA and minB
	if minA < minB {
		fmt.Printf("%d%d\n", minA, minB)
	} else {
		fmt.Printf("%d%d\n", minB, minA)
	}
}

